SELECT combined_lost.*, combined_lost.dataSource, f.id AS file_id, f.atc_id AS file_atc_id, f.fd_filepath_img, f.save_name, f.file_size, f.file_path FROM( SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, created_at, updated_at, done, is_deleted, lst_filepath_img, 'user' AS dataSource FROM lost WHERE is_deleted=0 And atc_id = #{atcId}
UNION ALL
SELECT num, atc_id, id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, created_at, updated_at, done, is_deleted, lst_filepath_img, 'police' AS dataSource FROM lost_police WHERE is_deleted=0 And atc_id = #{atcId} ) combined_lost LEFT JOIN lost_file f on combined_lost.atc_id=f.atc_id ORDER BY f.id ASC

